import{_ as e,c as s,o as a,a3 as r}from"./chunks/framework.Dokpd4od.js";const g=JSON.parse('{"title":"Inventory","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/index.md","filePath":"master/supply-chain/inventories/index.md","lastUpdated":1792041590000}'),o={name:"master/supply-chain/inventories/index.md"};function n(d,t,i,h,l,u){return a(),s("div",null,t[0]||(t[0]=[r(`<h1 id="inventory" tabindex="-1">Inventory <a class="header-anchor" href="#inventory" aria-label="Permalink to &quot;Inventory&quot;">​</a></h1><p>Inventory is the part of Aureus ERP that knows what you own, where it sits and where it is going. Every time goods arrive, move, leave or get counted, Inventory records it. Purchase, Sales, Manufacturing and Point of Sale all feed stock into this one place.</p><blockquote><p><strong>In simple words:</strong> Inventory answers three questions: what do I have, where is it, and what is on its way.</p></blockquote><h2 id="the-whole-stock-flow" tabindex="-1">The whole stock flow <a class="header-anchor" href="#the-whole-stock-flow" aria-label="Permalink to &quot;The whole stock flow&quot;">​</a></h2><p>Stock always travels between <strong>locations</strong>. A location is a place, such as the vendor, a shelf in your warehouse or the customer. Each movement is recorded on a document called a <strong>transfer</strong>. Read the flow in six stages.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Set up  →  2. Receive  →  3. Store  →  4. Count  →  5. Deliver  →  6. Report</span></span></code></pre></div><ol><li><strong>Set up.</strong> Turn on the settings you need, check your warehouse and locations, and make products that track inventory. See <a href="./get-started/">Get started</a>.</li><li><strong>Receive.</strong> A confirmed purchase order creates a receipt. When the goods arrive, you validate the receipt and stock enters your warehouse.</li><li><strong>Store.</strong> Goods go to a shelf or zone. Putaway rules, storage categories and packages help you keep them organised.</li><li><strong>Count.</strong> You compare the system quantity with the shelves. Adjustments fix the difference, and scrap removes damaged goods.</li><li><strong>Deliver.</strong> A confirmed sales order creates a delivery. You pick, pack and ship, then validate. Stock leaves your warehouse.</li><li><strong>Report.</strong> Moves History shows every movement. The stock report shows what sits in each location right now.</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vendor  →  WH/Input  →  WH/Stock  →  WH/Output  →  Customer</span></span>
<span class="line"><span> (buy)     (receive)    (store)       (ship)         (sell)</span></span></code></pre></div><p>How many boxes in the middle you use depends on one or two, or three steps per warehouse. See <a href="./routes/">Routes</a>.</p><h2 id="settings-that-reveal-menus" tabindex="-1">Settings that reveal menus <a class="header-anchor" href="#settings-that-reveal-menus" aria-label="Permalink to &quot;Settings that reveal menus&quot;">​</a></h2><p>Some menus and fields stay hidden until you turn on a setting. Go to <code>Inventory → Settings</code> and switch on what you need. See <a href="./get-started/inventory-settings.html">Inventory settings</a>.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Settings page</th><th>What it reveals</th></tr></thead><tbody><tr><td><strong>Locations</strong></td><td>Manage Warehouses</td><td><strong>Locations</strong> menu, location fields on transfers and operation types</td></tr><tr><td><strong>Multi Steps Routes</strong></td><td>Manage Warehouses</td><td><strong>Routes</strong>, <strong>Rules</strong>, and the step choices on a warehouse</td></tr><tr><td><strong>Lots &amp; Serial Numbers</strong></td><td>Manage Traceability</td><td><strong>Lots / Serial Numbers</strong> menu, <strong>Track By</strong> on products</td></tr><tr><td><strong>Packages</strong></td><td>Manage Operations</td><td><strong>Packages</strong> and <strong>Package Types</strong> menus</td></tr><tr><td><strong>Packagings</strong></td><td>Manage Products</td><td><strong>Packagings</strong> menu, <strong>Packaging</strong> columns on order lines</td></tr><tr><td><strong>Variants</strong></td><td>Manage Products</td><td><strong>Attributes</strong> menu</td></tr><tr><td><strong>Unit of Measure</strong></td><td>Manage Products</td><td><strong>UOM Categories</strong> menu, unit fields</td></tr><tr><td><strong>Dropshipping</strong></td><td>Manage Logistics</td><td><strong>Dropships</strong> under Operations</td></tr></tbody></table><h2 id="groups-in-this-guide" tabindex="-1">Groups in this guide <a class="header-anchor" href="#groups-in-this-guide" aria-label="Permalink to &quot;Groups in this guide&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>What you learn</th></tr></thead><tbody><tr><td><a href="./get-started/">Get started</a></td><td>The Overview dashboard, settings and a first tutorial</td></tr><tr><td><a href="./products/">Products</a></td><td>Storable products, categories, attributes, packagings and units</td></tr><tr><td><a href="./tracking/">Tracking</a></td><td>Lots, serial numbers and packages</td></tr><tr><td><a href="./warehouses/">Warehouses</a></td><td>Warehouses, locations, operation types and storage categories</td></tr><tr><td><a href="./operations/">Operations</a></td><td>Receipts, deliveries, internal transfers and dropships</td></tr><tr><td><a href="./adjustments/">Adjustments</a></td><td>Inventory counts and scrap</td></tr><tr><td><a href="./routes/">Routes</a></td><td>One, two and three step flows, rules and putaway</td></tr><tr><td><a href="./reporting/">Reporting</a></td><td>Moves History and the stock report</td></tr><tr><td><a href="./barcode/">Barcode</a></td><td>Scan operations and counts on a phone or scanner</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./get-started/inventory-overview.html">Inventory overview</a></li><li><a href="./get-started/first-steps.html">First steps tutorial</a></li><li><a href="./../purchase/orders/purchase-orders.html">Purchase orders</a></li><li><a href="./../../sales/sales/products-prices/manage-products.html">Manage products in Sales</a></li></ul>`,16)]))}const p=e(o,[["render",n]]);export{g as __pageData,p as default};
